// ---- Global status bar (lv_layer_sys → drawn above everything) ----
// Always-visible 240×22 strip across the top of the display. Left zone is
// dynamic (MESHCOMOD on Home tab, mail-icon + total-unread count on the
// other tabs). Right zone is a fixed stack: connection icon (WiFi or
// BLE, whichever is up), clock, battery percent, battery icon. The bar
// sits on lv_layer_sys so modals on lv_layer_top can't cover it, and the
// tabview / chat overlay are explicitly sized to leave the top 22 px
// clear.
// Runtime (not constexpr) so the UI-scale can grow it to fit bigger status-bar text — set to SC(22)
// once at boot in begin(), before the UI is built. Stays 22 on the non-scaled boards.
static lv_coord_t STATUSBAR_H = 22;
#if CAP_ROUND_CORNERS
// Two-row status bar for the round-cornered phone panel: row 1 (top) holds the app name +
// clock, row 2 (bottom) holds the wifi/ble/sd/signal/battery cluster. A top pad clears the
// corner arc; a horizontal inset keeps the end glyphs out of the left/right arcs. STATUSBAR_H
// is set to (top pad + two rows) at boot so every page reserves the taller bar, and the bar
// stays this fixed height in ALL states (no *2 doubling — the tall personalities reuse the
// two rows). Text tops (ROW1_Y / ROW2_Y) are tuned so the small g_font glyphs sit centred.
static constexpr lv_coord_t SB_ROW     = 22;                       // one status-bar row
static constexpr lv_coord_t SB_TOP_PAD = 8;                        // clear the top corner arc
static constexpr lv_coord_t SB_INSET_X = 16;                       // left/right corner safe-area
static constexpr lv_coord_t SB_ROW1_Y  = SB_TOP_PAD + 2;           // ~10 text top, row 1 (clock)
static constexpr lv_coord_t SB_ROW2_Y  = SB_TOP_PAD + SB_ROW + 3;  // ~33 text top, row 2 (name + status)
static void statusBarLayoutTwoRow(int slide);   // defined just after buildGlobalStatusBar
#endif
// True while the Reader/Web page is collapsed and showing its URL in the status bar's
// title zone — updateGlobalStatusBar then hides the clock to make room for the URL.
static bool s_reader_bar_url = false;
// True whenever the Reader/Web page is open — suppresses the tall status-bar glass
// fade so the address reads on a solid bar (no gradient behind it).
static bool s_reader_page_open = false;
struct GlobalStatusBar {
  lv_obj_t* root;
  lv_obj_t* left_label;
  lv_obj_t* conn_icon;       // Wi-Fi glyph
  lv_obj_t* ble_icon;        // Bluetooth glyph (separate from Wi-Fi)
  lv_obj_t* sleep_icon;      // idle light-sleep readiness indicator (T-Deck only)
  lv_obj_t* dnd_icon;        // Do Not Disturb active glyph (moon, all boards)
  lv_obj_t* sd_icon;         // microSD read/write activity LED (left of Wi-Fi)
  lv_obj_t* async_icon;      // async mesh-request spinner glyph (centre, transient)
  lv_obj_t* clock;
  lv_obj_t* batt_pct;
  lv_obj_t* batt_icon;
  lv_obj_t* layout_label;   // EN / BG indicator, right side
  lv_obj_t* chan_gear;      // channel-settings gear, left of the thread name (channels only)
  lv_obj_t* sig_bars[4];    // mesh signal-strength bars (lit count = last-heard SNR)
  lv_obj_t* sig_box;        // container holding sig_bars (slides over when charging hides the %)
  lv_obj_t* inbox_add;      // chat/channel-overview actions: [+ add | ✓ read | QR]
  lv_obj_t* inbox_mark;
  lv_obj_t* inbox_qr;
  lv_obj_t* chat_back;      // "‹" affordance shown while in a chat (tap the bar = close)
  lv_obj_t* fade;           // glass backdrop for the lower row in a chat/overview: top-row solid,
                            //   fading to translucent at the bottom so the chat shows through it
  lv_obj_t* dim;            // full-bar scrim shown while a modal popup is up, so the bar dims with
                            //   the rest of the screen (the popup's own backdrop starts below it)
};
static GlobalStatusBar g_statusbar = {};
static void updateGuardianHomeBar();
static inline void setLabelIfChanged(lv_obj_t* lbl, const char* txt);
static void updateGlobalStatusBar();   // fwd decl, called from refresh tick

// Settings detail pages render the global status bar at DOUBLE height: the bar's
// back chevron + page title then read like a tall title bar (the whole bar still
// taps to go Back — see statusBarTapCb), and the extra room is free for future
// per-page header content. updateGlobalStatusBar enlarges the back label while tall.
static bool s_statusbar_tall = false;
// Generic "app page" hook so full-screen tool pages (RF Monitor, Spectrum) get the SAME
// tall status-bar + back-chevron treatment as settings detail pages — NOT a second header
// bar. When uiApplication.pageTitle() is set, updateGlobalStatusBar goes tall and paints "‹ <title>"
// centred in the bar; a tap on the bar calls uiApplication.pageClose() (see statusBarTapCb).
// Slim variant: the page keeps the "‹ title" + tap-to-close bar behavior but the
// bar stays ONE line — no double-height glass row (the Lua Store's tab bar sits
// right at the top of its content, which the glass row used to sit over).
#if CAP_ROUND_CORNERS
// The round-panel bar is already two rows tall in every state — the tall personalities
// (settings title, inbox actions, open chat) reuse the two rows rather than doubling it.
static inline lv_coord_t statusBarCurH() { return STATUSBAR_H; }
#else
static inline lv_coord_t statusBarCurH() { return s_statusbar_tall ? (lv_coord_t)(STATUSBAR_H * 2) : STATUSBAR_H; }
#endif
static void statusBarSetTall(bool tall) {
  s_statusbar_tall = tall;
  if (g_statusbar.root) lv_obj_set_height(g_statusbar.root, statusBarCurH());
  // (updateGlobalStatusBar drives this every tick + refreshes the left zone; it must
  // NOT be called from here — it calls back into statusBarSetTall = recursion.)
}

void reserveTileFetchStack();   // fwd: claim the worker stack before Wi-Fi eats the heap

// ---- AppPage: the shared full-screen app-page chrome (see AppPage.h) --------------
// Thin wrappers over the machinery just above, exported so the self-contained app
// modules (SnakeGame) build the same page as the in-file tool
// pages instead of hand-rolling it against a hardcoded bar height.
lv_coord_t appPageContentTop() { return STATUSBAR_H; }
lv_coord_t appPageContentH()   { return (lv_coord_t)(lv_disp_get_ver_res(nullptr) - STATUSBAR_H); }

lv_obj_t* appPageCreateRoot(uint32_t bg_color) {
  lv_obj_t* root = lv_obj_create(lv_layer_top());
  lv_obj_remove_style_all(root);
  lv_obj_set_size(root, lv_disp_get_hor_res(nullptr), appPageContentH());
  lv_obj_set_pos(root, 0, appPageContentTop());
  lv_obj_set_style_bg_color(root, lv_color_hex(bg_color), LV_PART_MAIN);
  lv_obj_set_style_bg_opa(root, LV_OPA_COVER, LV_PART_MAIN);
  lv_obj_clear_flag(root, LV_OBJ_FLAG_SCROLLABLE);
  // CLICKABLE is what makes the page modal: every press lands here instead of falling
  // through to the tab bar / list underneath.
  lv_obj_add_flag(root, LV_OBJ_FLAG_CLICKABLE);
  return root;
}

void appPageBegin(const char* title, void (*close_fn)()) {
  uiApplication.beginPage(title, close_fn);
  statusBarSetTall(true);
  updateGlobalStatusBar();
}

void appPageBeginSlim(const char* title, void (*close_fn)()) {
  uiApplication.beginPage(title, close_fn, true);
  statusBarSetTall(false);
  updateGlobalStatusBar();
}

void appPageCollapseTitle(void (*close_fn)()) {
  if (!uiApplication.collapsePage(close_fn)) return;
  statusBarSetTall(false);
  updateGlobalStatusBar();
}
void appPageEnd(void (*close_fn)()) {
  if (!uiApplication.endPage(close_fn)) return;
  statusBarSetTall(false);
  updateGlobalStatusBar();
}

void appPageDeleteRootAsync(lv_obj_t* root) {
  if (root) lv_obj_del_async(root);
}
