  switch (m) {
    case CONTACTS_SORT_AZ:         return "Name (A-Z)";
    case CONTACTS_SORT_LAST_HEARD: return "Recently heard";
    case CONTACTS_SORT_LAST_MSG:   return "Recent message";
    case CONTACTS_SORT_DISTANCE:   return "Nearest first";
  }
