static void versionCheckUpdateUi() {
  lv_obj_t* badges[2] = { s_update_badge, settingsScreen.badge() };
  for (lv_obj_t* badge : badges) {
    if (!badge) continue;
    if (s_update_available) lv_obj_clear_flag(badge, LV_OBJ_FLAG_HIDDEN);
    else lv_obj_add_flag(badge, LV_OBJ_FLAG_HIDDEN);
  }
  firmwareUpdatePanel.refresh({releaseMonitor.latest(), releaseMonitor.checked(), touchPrefsGetBetaUpdates()});
}

static ui::screens::FirmwareUpdatePanel::Host firmwareUpdateHost() {
  return {nullptr,
    [](void*) -> bool {
#if defined(ESP32) && defined(MULTI_TRANSPORT_COMPANION)
      return ensureTileFetchTaskRunning();
#else
      return false;
#endif
    },
    [](void*) -> bool {
#if defined(MULTI_TRANSPORT_COMPANION)
      return WiFi.status() == WL_CONNECTED;
#else
      return false;
#endif
    },
    [](void*) -> bool {
#if defined(ESP32) && defined(MULTI_TRANSPORT_COMPANION) && CAP_OTA
      return ui::platform::hasOtaUpdateSlot();
#else
      return false;
#endif
    },
    [](void*, const char* message, int duration) { if (g_lv.task) g_lv.task->showAlert(message, duration); },
    [](void*) { if (g_lv.task) g_lv.task->rebootDevice(); },
    [](void*, bool beta) {
      touchPrefsSetBetaUpdates(beta);
      ui::screens::releasePicker::close();
      releaseMonitor.selectChannel(beta);
      s_update_available = false;
      versionCheckUpdateUi();
      if (g_lv.task) g_lv.task->showAlert(beta ? TR("Test builds: on") : TR("Test builds: off"), 2000);
    },
    [](void*, int latest, bool beta) { ui::screens::releasePicker::open(latest, beta); }
  };
}
static void buildFirmwareUpdatePanel(lv_obj_t* page, lv_coord_t width) {
  ui::screens::FirmwareUpdatePanel::Options options{FIRMWARE_VERSION, firmwareReleaseN(), false, false, false, false};
#if defined(ESP32) && defined(MULTI_TRANSPORT_COMPANION)
  options.channelControls = FIRMWARE_OTA_ENV[0] != 0;
#if CAP_OTA
  options.ota = ui::platform::hasOtaUpdateSlot();
#if CAP_SD
  options.sd = true;
#endif
#endif
#endif
#if defined(HAS_TDECK_GT911)
  options.launcher = true;
#endif
  firmwareUpdatePanel.build(page, width, options,
    {releaseMonitor.latest(), releaseMonitor.checked(), touchPrefsGetBetaUpdates()});
}

// Trigger a check once Wi-Fi is up (then every 6 h); apply the result when ready.
static void versionCheckService(unsigned long now) {
  firmwareUpdatePanel.poll(static_cast<uint32_t>(now));
#if defined(MULTI_TRANSPORT_COMPANION)
  const bool changed = releaseMonitor.selectChannel(touchPrefsGetBetaUpdates());
  const bool ready = WiFi.status() == WL_CONNECTED && (uint32_t)WiFi.localIP() != 0;
  const bool completed = releaseMonitor.tick(firmwareUpdates, now, ready, firmwareReleaseN(), ensureTileFetchTaskRunning);
  if (changed || completed) {
    s_update_available = releaseMonitor.latest() > firmwareReleaseN();
    versionCheckUpdateUi();
  }
#else
  (void)now;
#endif
}

static void applySwipeGesture(int8_t swipe_x, int8_t swipe_y) {
  // The Snake game owns the whole screen while it's open: steer with the swipe
  // and return, so it can never reach the tab switcher / map pan / control
  // centre behind the overlay. This reuses the per-board hardware swipe detector
  // that drives tab switching (reliable on both the V4 cap-touch and the T-Deck
  // GT911), since LVGL's own LV_EVENT_GESTURE doesn't fire dependably on the
  // cap-touch — so this, not SnakeGame's gestureCb, is what makes touch steering
  // actually work. swipe_x<0 == left, swipe_y<0 == up (see the control-center
  // note below for the sign convention).
  if (luaAppIsOpen()) {   // Lua apps get the same reliable hardware swipes as Snake did
    if (swipe_x != 0)      luaAppSteer(swipe_x < 0 ? -1 : 1, 0);
    else if (swipe_y != 0) luaAppSteer(0, swipe_y < 0 ? -1 : 1);
    return;
  }
  if (SnakeGame::isOpen()) {
    if (swipe_x != 0)      SnakeGame::steer(swipe_x < 0 ? -1 : 1, 0);
    else if (swipe_y != 0) SnakeGame::steer(0, swipe_y < 0 ? -1 : 1);
    return;
  }
  // Every OTHER full-screen app page (Airtime, Spectrum, RF Monitor, Discover, VNC, Remote,
  // Reader) also owns the screen, so swallow the swipe instead of letting it reach the tab
  // switcher behind the page. Making the page root opaque + CLICKABLE only stops CLICKS:
  // this detector reads the per-board touch hardware directly and never consults LVGL
  // hit-testing, which is why a swipe inside Airtime still jumped to the Map tab. Settings
  // sub-sheets borrow uiApplication.pageTitle() for their back chevron too, but they always open from
  // inside a category and have their own rightward swipe-back further down, so exclude them.
  // (Vertical swipes are a no-op at the end of this function, so this only kills tab swipes.)
  if (uiApplication.pageTitle() && s_settings_open_cat < 0) return;
  // A slider was just being dragged — its horizontal drag must NOT be read as a
  // tab/back swipe (e.g. raising the volume slider rightward kept triggering the
  // settings "swipe right = back"). Ignore swipes briefly after any slider touch.
  if (s_slider_touch_ms && (millis() - s_slider_touch_ms) < 500) return;
  // An open chat/channel: a left→right (rightward) swipe closes it (iOS-style
  // back). Any other swipe is swallowed so the conversation keeps the screen.
  if (hasChatDetailOpen()) {
    if (swipe_x > 0) {
      if (g_lv.dm.detail_open)      closeChatPanel(&g_lv.dm);
      else if (g_lv.ch.detail_open) closeChatPanel(&g_lv.ch);
    }
    return;
  }
  if (overlayBlocksTabSwipe()) return;   // theme / channel-scope pickers: don't swipe the menu beneath
  // The control center drops down from the top bar, so an up-swipe dismisses
  // it (natural "push it back up" gesture). Any other swipe is swallowed so
  // that e.g. dragging its brightness slider can't also switch the tab
  // underneath the card. swipe_y < 0 == upward (see TDeckTouch swipe sign).
  if (s_cc_root) {
    if (swipe_y < 0) closeControlCenter();
    return;
  }
  // Popups floating over the app drawer (or any tab): swallow the swipe so it
  // can't switch tabs / close the drawer underneath them.
  if (drawerPopupOpen()) return;
  if (!g_lv.tabview) return;
  if (swipe_x != 0) {
    // An open settings detail sheet: a left→right (rightward) swipe goes Back,
    // like iOS edge-back. Any other swipe is swallowed so the tab underneath the
    // sheet never switches.
    if (s_settings_sheet) {
      if (swipe_x > 0) closeSettingsCategory();
      return;
    }
    // A settings modal overlays the tab — never switch under it.
    if (settingsModalIsOpen()) return;
    // Block horizontal tab-swipes on the Map tab — that gesture is "pan"
    // there, not "switch tab". The +/− and recenter buttons + the tabbar
    // icons remain the only way off the tab.
    if (getActiveTab() == MAP_TAB_INDEX) return;
    int idx = getActiveTab();
    int next = idx + (swipe_x < 0 ? 1 : -1);
    if (next < 0) next = 0;
    if (next > TAB_LAST) next = TAB_LAST;
    if (next != idx) goToTab(next);
    return;
  }
  // Vertical swipes intentionally fall through: LVGL's native drag-scroll on
  // the underlying list (chats / contacts / settings tab) handles them
  // continuously during the gesture, which feels naturally finger-locked.
  // The old fixed-step jump on release was the source of "jittery / jumpy"
  // vertical scroll feel.
  (void)swipe_y;
}

