static void openDiscoveredModalCb(lv_event_t* e) {
  if (lv_event_get_code(e) != LV_EVENT_CLICKED) return;
  lv_obj_t* body = createSettingsModal(TR("Discovered"), SettingsModalKind::Discovered);
  int y = 0;

  // Auto-add hint: any of the four "auto-add" type bits set means new contacts
  // of those kinds bypass this list and land straight in the Contacts tab.
  // Surfacing it here avoids the "where did my discoveries go?" confusion.
  {
    NodePrefs* prefs = the_mesh.getNodePrefs();
    const uint8_t mask = prefs ? (prefs->autoadd_config & static_cast<uint8_t>(
        AUTO_ADD_CHAT | AUTO_ADD_REPEATER | AUTO_ADD_ROOM_SERVER | AUTO_ADD_SENSOR)) : 0u;
    if (mask) {
      char hint[240];   // translations run long; the HU string is ~1.6x English
      char types[128]; types[0] = '\0';   // 4 translated plurals, UTF-8
      size_t off = 0;
      auto add = [&](const char* s) {
        if (off > 0 && off + 3 < sizeof(types)) { types[off++] = ','; types[off++] = ' '; types[off] = '\0'; }
        size_t n = strlen(s);
        if (off + n < sizeof(types)) { memcpy(types + off, s, n); off += n; types[off] = '\0'; }
      };
      if (mask & AUTO_ADD_CHAT)        add(TR("chats"));
      if (mask & AUTO_ADD_REPEATER)    add(TR("repeaters"));
      if (mask & AUTO_ADD_ROOM_SERVER) add(TR("rooms"));
      if (mask & AUTO_ADD_SENSOR)      add(TR("sensors"));
      snprintf(hint, sizeof(hint), TR("Auto-add on for %s — new %s land in Contacts automatically."),
               types, types);
      lv_obj_t* l = lv_label_create(body);
      lv_label_set_long_mode(l, LV_LABEL_LONG_WRAP);
      lv_obj_set_width(l, lv_pct(100));
      lv_label_set_text(l, hint);
      lv_obj_set_style_text_color(l, lv_color_hex(colors().COLOR_ACCENT), LV_PART_MAIN);
      lv_obj_set_style_text_font(l, &font12(), LV_PART_MAIN);
      lv_obj_set_pos(l, 2, y);
      // The text names every enabled type TWICE ("Auto-add on for chats,
      // repeaters, rooms, sensors — new chats, repeaters, rooms, sensors land
      // in Contacts automatically."), so with several types enabled it wraps
      // well past the fixed SC(38) and printed over the first discovered card.
      lv_obj_update_layout(l);
      y += LV_MAX(SC(38), lv_obj_get_height(l) + SC(6));
    }
  }

  // Collect the not-yet-contact discovered slots, then sort by the selected mode.
  const double disc_self_lat = g_lv.task ? g_lv.task->getNodeLat() : 0.0;
  const double disc_self_lon = g_lv.task ? g_lv.task->getNodeLon() : 0.0;
  int order[DISCOVERED_MAX];
  int n = 0;
  for (int i = 0; i < DISCOVERED_MAX; ++i) {
    if (!(s_discovered[i].used && !s_discovered[i].in_contacts)) continue;
    // Distance sort needs a location — exclude entries with none from the results.
    if (g_disc_sort == DISC_SORT_DISTANCE &&
        s_discovered[i].ci.gps_lat == 0 && s_discovered[i].ci.gps_lon == 0) continue;
    order[n++] = i;
  }
  // Insertion sort honouring g_disc_sort + the asc/desc flip (default: newest first).
  for (int i = 1; i < n; ++i) {
    int v = order[i];
    int j = i - 1;
    while (j >= 0 && discSortBefore(v, order[j], disc_self_lat, disc_self_lon)) {
      order[j + 1] = order[j];
      --j;
    }
    order[j + 1] = v;
  }

  // Header buttons left of Close: a cogwheel (Discovered settings) always, plus a
  // red trash (Purge all) when there's something to purge. Header is the modal
  // root's first child.
  if (g_set_modal.root) {
    lv_obj_t* header = lv_obj_get_child(g_set_modal.root, 0);
    if (header) {
      lv_obj_t* cog = lv_btn_create(header);
      lv_obj_set_size(cog, SC(32), SC(32));
      lv_obj_align(cog, LV_ALIGN_RIGHT_MID, -68, 0);   // just left of the 58 px "Close" (at -6)
      styleButton(cog);
      lv_obj_add_event_cb(cog, openDiscoveredSettingsSheetCb, LV_EVENT_CLICKED, nullptr);
      lv_obj_t* cl = lv_label_create(cog);
      useChainedFont(cl);
      lv_label_set_text(cl, LV_SYMBOL_SETTINGS);
      lv_obj_set_style_text_color(cl, lv_color_hex(colors().COLOR_TEXT), LV_PART_MAIN);
      lv_obj_center(cl);
      // Sort (⇅) — opens the discovered sort sheet (Recently heard / Name / Nearest,
      // each asc/desc). Always present so the control is visible even on an empty list.
      lv_obj_t* srt = lv_btn_create(header);
      lv_obj_set_size(srt, SC(32), SC(32));
      lv_obj_align(srt, LV_ALIGN_RIGHT_MID, -106, 0);   // left of the cog
      styleButton(srt);
      lv_obj_add_event_cb(srt, openDiscSortSheetCb, LV_EVENT_CLICKED, nullptr);
      lv_obj_t* srtl = lv_label_create(srt);
      useChainedFont(srtl);
      lv_label_set_text(srtl, LV_SYMBOL_SHUFFLE);
      lv_obj_set_style_text_color(srtl, lv_color_hex(colors().COLOR_TEXT), LV_PART_MAIN);
      lv_obj_center(srtl);
      if (n > 0) {
        lv_obj_t* pb = lv_btn_create(header);
        lv_obj_set_size(pb, SC(32), SC(32));
        lv_obj_align(pb, LV_ALIGN_RIGHT_MID, -144, 0);   // left of the sort
        styleButton(pb);
        lv_obj_set_style_bg_color(pb, lv_color_hex(themeRole(0x7A2A2A, colors().COLOR_STATUS_DANGER)), LV_PART_MAIN);
        lv_obj_set_style_text_color(pb, lv_color_hex(colors().COLOR_ON_STATUS_DANGER), LV_PART_MAIN);
        lv_obj_add_event_cb(pb, discoveredPurgeCb, LV_EVENT_CLICKED, nullptr);
        lv_obj_t* pl = lv_label_create(pb);
        useChainedFont(pl);
        lv_label_set_text(pl, LV_SYMBOL_TRASH);
        lv_obj_set_style_text_color(pl, lv_color_hex(colors().COLOR_ON_STATUS_DANGER), LV_PART_MAIN);
        lv_obj_center(pl);
      }
    }
  }

  if (n == 0) {
    lv_obj_t* empty = lv_label_create(body);
    lv_label_set_long_mode(empty, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(empty, lv_pct(100));
    lv_obj_set_pos(empty, 2, y + 8);
    lv_obj_set_style_text_color(empty, lv_color_hex(colors().COLOR_SUB), LV_PART_MAIN);
    lv_obj_set_style_text_font(empty, &font12(), LV_PART_MAIN);
    lv_label_set_text(empty,
      TR("No discovered nodes yet.\n\n"
      "Anything heard over the air that isn't in your contacts will show up "
      "here. When auto-add is off, you can manually add nodes to your contacts."));
    return;
  }

  for (int k = 0; k < n; ++k) {
    int idx = order[k];
    LvDiscoveredEntry& e_disc = s_discovered[idx];

    // Card background — full content width (was a fixed 222 px, leaving a gap).
    const lv_coord_t cw     = s_settings_content_w;
    const int        pad    = 4, add_w = 56, gap = 8;
    const lv_coord_t card_h = 52;
    const lv_coord_t name_h = lv_font_get_line_height(&font14());
    // Leading type icon, matching the Contacts rows (#459) — the Discover pane was
    // the only list without one, so a repeater and a peer looked identical until you
    // read the meta line. Same glyph set and the same 22 px column.
    const int        icon_w = 22;
    const int        text_x = 2 + icon_w;
    const lv_coord_t text_w = cw - 2 * pad - add_w - gap - icon_w;   // room for name/meta beside Add

    lv_obj_t* card = lv_obj_create(body);
    lv_obj_remove_style_all(card);
    lv_obj_set_size(card, cw, card_h);
    lv_obj_set_pos(card, 0, y);
    lv_obj_set_style_bg_opa(card, LV_OPA_COVER, LV_PART_MAIN);
    lv_obj_set_style_bg_color(card, lv_color_hex(colors().COLOR_PANEL), LV_PART_MAIN);
    lv_obj_set_style_radius(card, 6, LV_PART_MAIN);
    lv_obj_set_style_pad_all(card, pad, LV_PART_MAIN);
    lv_obj_clear_flag(card, LV_OBJ_FLAG_SCROLLABLE);

    // Type icon (person = peer, antenna = repeater, loop = room). FontAwesome PUA
    // glyphs resolve through font16()'s fallback chain, so the label must render in
    // font16() — same rule as the Contacts rows.
    {
      const bool is_rep = (e_disc.ci.type == ADV_TYPE_REPEATER);
      lv_obj_t* ic = lv_label_create(card);
      lv_label_set_text(ic, is_rep ? TOUCH_SYM_ANTENNA
                          : (e_disc.ci.type == ADV_TYPE_ROOM ? LV_SYMBOL_LOOP : TOUCH_SYM_PERSON));
      lv_obj_set_style_text_font(ic, &font16(), LV_PART_MAIN);
      lv_obj_set_style_text_color(ic, lv_color_hex(colors().COLOR_SUB), LV_PART_MAIN);
      lv_obj_align(ic, LV_ALIGN_LEFT_MID, 2, 0);
    }

    // Name label — clamped to ONE line (height = line height) so a long name
    // ellipsises instead of wrapping down onto the meta row below it.
    lv_obj_t* nm = lv_label_create(card);
    useChainedFont(nm);
    char nm_buf[40];
    copyUtf8ReplacingMissingGlyphs(&font14(), nm_buf, sizeof(nm_buf), e_disc.ci.name);
    lv_label_set_text(nm, nm_buf[0] ? nm_buf : "(unnamed)");
    lv_obj_set_style_text_color(nm, lv_color_hex(colors().COLOR_TEXT), LV_PART_MAIN);
    lv_label_set_long_mode(nm, LV_LABEL_LONG_DOT);
    lv_obj_set_size(nm, text_w, name_h);
    lv_obj_set_pos(nm, text_x, 3);

    // Type + hops + key prefix (single line, ellipsised, below the name)
    lv_obj_t* meta = lv_label_create(card);
    useChainedFont(meta);
    const char* type_label = "node";
    switch (e_disc.ci.type) {
      case ADV_TYPE_NONE:     type_label = "none";     break;
      case ADV_TYPE_CHAT:     type_label = "chat";     break;
      case ADV_TYPE_REPEATER: type_label = "repeater"; break;
      case ADV_TYPE_ROOM:     type_label = "room";     break;
      case ADV_TYPE_SENSOR:   type_label = "sensor";   break;
      default: break;
    }
    char keyhex[18];
    mesh::Utils::toHex(keyhex, e_disc.ci.id.pub_key, 4);
    keyhex[8] = '\0';
    char meta_buf[64];
    // 0xFF is OUT_PATH_UNKNOWN, not a hop count: an advert that arrived by flood
    // has no known path, and printing it raw showed "255 hop", which reads as a
    // hop count far beyond any real one (#394). Direct is worth saying plainly,
    // and a count needs its plural or every multi-hop row reads as broken.
    char hop_buf[16];
    if (e_disc.path_len == OUT_PATH_UNKNOWN) snprintf(hop_buf, sizeof(hop_buf), "%s", TR("path unknown"));
    else if (e_disc.path_len == 0)           snprintf(hop_buf, sizeof(hop_buf), "%s", TR("direct"));
    else snprintf(hop_buf, sizeof(hop_buf), "%u %s", (unsigned)e_disc.path_len,
                  e_disc.path_len == 1 ? TR("hop") : TR("hops"));
    snprintf(meta_buf, sizeof(meta_buf), "%s · %s · %s…", type_label, hop_buf, keyhex);
    lv_label_set_text(meta, meta_buf);
    lv_obj_set_style_text_color(meta, lv_color_hex(colors().COLOR_SUB), LV_PART_MAIN);
    lv_obj_set_style_text_font(meta, &font12(), LV_PART_MAIN);
    lv_label_set_long_mode(meta, LV_LABEL_LONG_DOT);
    lv_obj_set_width(meta, text_w);
    lv_obj_set_pos(meta, text_x, 3 + name_h + 2);

    // "Add" button on the right, vertically centred
    lv_obj_t* add_btn = lv_btn_create(card);
    lv_obj_set_size(add_btn, add_w, card_h - 2 * pad - 2);
    lv_obj_align(add_btn, LV_ALIGN_RIGHT_MID, 0, 0);
    styleButton(add_btn);
    s_disc_add_ctx[idx].slot_idx = idx;
    lv_obj_add_event_cb(add_btn, discoveredAddCb, LV_EVENT_CLICKED, &s_disc_add_ctx[idx]);
    lv_obj_t* add_lbl = lv_label_create(add_btn);
    useChainedFont(add_lbl);
    lv_label_set_text(add_lbl, TR("Add"));
    lv_obj_center(add_lbl);

    y += card_h + 6;
  }
}

