// Single-character spam filter. A lot of mesh spam is a 1-byte payload — the cheapest
// message there is — and it still costs every receiver a notification and a chime.

// Location telemetry (#266). Separate from the plain telemetry switch on purpose:
// battery/environment is not position, and a single "allow telemetry" must never be
// able to hand out where you are. Dropdown order matches TELEM_MODE_*: 0 deny,
// 1 allow-flags (chosen contacts), 2 allow-all.



// LVGL parents an open dropdown list to the screen layer and, when the button
// sits in the lower half of a page, flips the list to drop *upward* — sliding
// its top edge behind our global status bar (which lives on lv_layer_sys, above
// everything) so the first option(s) get clipped. Run after the list is open &
// positioned (post-CLICKED) to cap its height to the area below the status bar
// and nudge it back on-screen. Wire onto every settings dropdown.
static void clampDropdownListCb(lv_event_t* e) {
  lv_obj_t* dd = lv_event_get_target(e);
  lv_obj_t* list = lv_dropdown_get_list(dd);
  if (!list || lv_obj_has_flag(list, LV_OBJ_FLAG_HIDDEN)) return;   // closed/just-closed
  // The open list is created on lv_scr_act, which sits BELOW the status bar (lv_layer_top),
  // so it tucks UNDER the topbar where they overlap. Reparent it to lv_layer_top and bring
  // it to the front so it always renders ON TOP of the bar. Both layers share the screen
  // origin, so the absolute position is preserved.
  if (lv_obj_get_parent(list) != lv_layer_top()) lv_obj_set_parent(list, lv_layer_top());
  lv_obj_move_foreground(list);
  const lv_coord_t ver   = lv_disp_get_ver_res(nullptr);
  const lv_coord_t bar   = statusBarCurH();                         // double height on settings pages
  const lv_coord_t avail = ver - bar;                              // usable height below the (current) bar
  lv_obj_update_layout(list);
  if (lv_obj_get_height(list) > avail) lv_obj_set_height(list, avail);  // too tall -> cap + let it scroll
  lv_obj_update_layout(list);
  const lv_coord_t h  = lv_obj_get_height(list);
  const lv_coord_t y1 = lv_obj_get_y(list);
  if (y1 < bar)            lv_obj_set_y(list, bar);                 // opened up into the status bar
  else if (y1 + h > ver)   lv_obj_set_y(list, ver - h);            // hangs off the bottom edge
}

// The standard dropdown look + behaviour, in one call (the settings pages spell the same
// thing out inline). Worth having as a helper because an UNSTYLED dropdown is subtly broken
// on a keyboard board: LVGL's stock theme is the LIGHT one, so the closed button and its open
// list render as near-white cards, where the accent focus glow has too little contrast.
// Panel colours fix that; the accent-filled selected row does the same job INSIDE an open
// list (the stock theme highlights it with its own blue primary, not the UI accent); and the
// clamp keeps a list that opens upward from sliding under the tall app-page title bar.
static void styleDropdown(lv_obj_t* dd) {
  lv_obj_set_style_text_font(dd, &font12(), LV_PART_MAIN);
  lv_obj_set_style_bg_color(dd, lv_color_hex(colors().COLOR_PANEL), LV_PART_MAIN);
  lv_obj_set_style_text_color(dd, lv_color_hex(colors().COLOR_TEXT), LV_PART_MAIN);
  lv_obj_set_style_border_color(dd, lv_color_hex(colors().COLOR_BORDER), LV_PART_MAIN);
  if (lv_obj_t* list = lv_dropdown_get_list(dd)) {   // created by the constructor, so it exists already
    lv_obj_set_style_bg_color(list, lv_color_hex(colors().COLOR_PANEL), LV_PART_MAIN);
    lv_obj_set_style_text_color(list, lv_color_hex(colors().COLOR_TEXT), LV_PART_MAIN);
    lv_obj_set_style_text_font(list, &font12(), LV_PART_MAIN);
    // The highlighted option (LVGL draws it in LV_PART_SELECTED with the CHECKED state).
    lv_obj_set_style_bg_color(list, lv_color_hex(colors().COLOR_ACCENT), LV_PART_SELECTED | LV_STATE_CHECKED);
    lv_obj_set_style_bg_opa(list, LV_OPA_COVER, LV_PART_SELECTED | LV_STATE_CHECKED);
    lv_obj_set_style_text_color(list, lv_color_hex(colors().COLOR_ON_ACCENT), LV_PART_SELECTED | LV_STATE_CHECKED);
  }
  lv_obj_add_event_cb(dd, clampDropdownListCb, LV_EVENT_CLICKED, nullptr);
}

// Signal-probe controls also live in the home-graph "Signal & traffic" popup;
// these handlers mirror it from the Radio settings page (same touch prefs).


// Opt-in (#64): scope direct/login/admin floods to the node's region. Persists + applies
// live. OFF by default (unscoped) so cross-region login/DMs keep working.

#if defined(HAS_TDISPLAY_P4)
// T-Display P4 LoRa antenna select. Applies live (no reboot) but is deliberately SESSION-ONLY:
// every boot re-forces the on-board antenna (see the boot-apply in begin() and the park in
// Xl9535::powerOnSequence). Transmitting into an external connector with no antenna fitted is
// what kills a PA, so the safe state has to be the one you get for free after a power cycle,
// and picking the external antenna has to be a fresh, explicit decision each time.
static lv_obj_t* s_p4_ant_dd = nullptr;   // showConfirm takes a bare callback, so stash the widget
static uint8_t   s_p4_ant_pending = Xl9535::ANT_INTERNAL;

static void radioP4AntennaConfirmApply() {
  xl9535.setAntennaMode(s_p4_ant_pending);   // takes effect on the very next transmit
  if (s_p4_ant_dd) lv_dropdown_set_selected(s_p4_ant_dd, s_p4_ant_pending);
  if (g_lv.task) {
    g_lv.task->showAlert(s_p4_ant_pending == Xl9535::ANT_EXTERNAL ? TR("External antenna selected")
                                                                  : TR("Per-transmit switching on"), 1200);
  }
}

static void radioP4AntennaSelectCb(lv_event_t* e) {
  if (lv_event_get_code(e) != LV_EVENT_VALUE_CHANGED) return;
  lv_obj_t* dd = lv_event_get_target(e);
  const uint8_t m = (uint8_t)lv_dropdown_get_selected(dd);
  if (m == Xl9535::ANT_INTERNAL) { xl9535.setAntennaMode(m); return; }   // always safe, no prompt

  // External moves BOTH directions onto the external socket, so it needs an antenna actually fitted
  // there — that is the one real hardware risk and it gets the damage warning. Auto (the legacy
  // per-TX toggle) transmits on the on-board antenna and only listens on the external socket, so it
  // is not a PA hazard, just permanently lopsided; it gets an accurate performance warning instead
  // of a scary one. Revert the widget FIRST and only re-select from the confirm handler: showConfirm
  // has no cancel callback, so a dismissed dialog must leave UI and hardware where they were.
  s_p4_ant_dd = dd;
  s_p4_ant_pending = m;
  lv_dropdown_set_selected(dd, xl9535.antennaMode());
  showConfirm(m == Xl9535::ANT_EXTERNAL
                ? TR("Switch to the external antenna?\n\nMake sure an antenna is actually connected "
                     "to the external antenna socket first. Transmitting with nothing attached can "
                     "damage the radio.\n\nResets to the on-board antenna on every reboot.")
                : TR("Turn on legacy per-transmit switching?\n\nDiagnostic mode, for comparison "
                     "only. It transmits on the on-board antenna and listens on the external one, "
                     "so your outbound signal will be much weaker than your inbound.\n\nResets to "
                     "the on-board antenna on every reboot."),
              TR("Switch"), radioP4AntennaConfirmApply);
}
#endif
#if defined(HELTEC_LORA_V4_TFT)
// Heltec V4.3 high-gain FEM LNA (~17 dB external receive amp). Persists + applies live.
static void radioFemLnaToggleCb(lv_event_t* e) {
  if (lv_event_get_code(e) != LV_EVENT_VALUE_CHANGED) return;
  const bool on = lv_obj_has_state(lv_event_get_target(e), LV_STATE_CHECKED);
  touchPrefsSetFemLna(on);
  board.setFemLnaEnable(on);
}
#endif
// Buffered LoRa receive (experimental): a drain task lifts each packet out of the
// radio within ~1 ms so a busy UI thread can't overwrite unread packets (the
