// Build a value snapshot at the host boundary. Formatting and widget refresh
// are independent of mesh, preferences, storage and ESP32 APIs.
static void readSystemDiagnostics(void *, bool details, ui::diagnostics::Snapshot &out) {
  out = ui::diagnostics::Snapshot{};
  ui::platform::readHardwareDiagnostics(out.hardware, details);
  out.nowSeconds = millis() / 1000u;
  out.stallCount = stallHistory.newest(out.stalls, 6);
  snprintf(out.firmware, sizeof out.firmware, "%s", FIRMWARE_VERSION);
  snprintf(out.buildDate, sizeof out.buildDate, "%s", FIRMWARE_BUILD_DATE);
#if defined(WADAMESH_FORK_BUILD)
  out.forkBuild = true;
#endif
#if defined(ESP32)
  if (!details) return;
  snprintf(out.clockSource, sizeof out.clockSource, "%s", rtc_clock.sourceName());
  out.clockCurrent = rtc_clock.timeIsCurrent();
#if defined(TLORA_PAGER) || defined(HAS_THINKNODE_M9)
  snprintf(out.rtcChip, sizeof out.rtcChip, "%s", hw_rtc.chipName());
  snprintf(out.rtcStatus, sizeof out.rtcStatus, "%s", HardwareRtcClock::statusName(hw_rtc.status()));
  out.rtcWriteVerified = hw_rtc.writeConfirmed();
#endif
  out.rxEvents = radio_driver.getRxEvents(); out.rxRead = radio_driver.getPacketsRecv();
  out.rxErrors = radio_driver.getPacketsRecvErrors(); out.rxDrops = radio_driver.getRxQueueDrops();
  out.rxBuffered = radio_driver.rxQueueEnabled();
  const auto &status = history.status();
  out.historySd = uiDataFsIsSdCard(); out.historyReady = status.ready;
  out.historySegments = status.segments; out.historyBytes = status.bytes;
  char when[16];
  if (status.failures) {
    char why[64]; chatSaveFailText(why, sizeof why);
    chatSaveStamp(when, sizeof when, status.failEpoch);
    snprintf(out.historySave, sizeof out.historySave, "FAIL x%u (%s)\n  %s",
             (unsigned)status.failures, when, why);
  } else if (status.okMs) {
    chatSaveStamp(when, sizeof when, status.okEpoch);
    snprintf(out.historySave, sizeof out.historySave, "OK %s", when);
  } else snprintf(out.historySave, sizeof out.historySave, "none this session");
#if CAP_MICROSD
  out.sdAvailable = true;
  out.sdChecked = s_sd_diag.checked; out.sdMounted = s_sd_diag.mounted;
  out.sdBeginOk = s_sd_diag.last_begin_ok; out.sdAttempts = s_sd_diag.attempts;
  out.sdHz = out.sdMounted ? s_sd_diag.mounted_hz : s_sd_diag.last_attempt_hz;
#if CAP_SD
  out.sdCapacitySupported = true;
  if (out.sdMounted) sdUsage.refresh(millis(), ensureTileFetchTaskRunning);
  const auto &usage = sdUsage.snapshot();
  out.sdCapacityDone = usage.done; out.sdCapacityOk = usage.ok;
  out.sdTotal = usage.total; out.sdFree = usage.free;
#endif
#endif
  out.contacts = the_mesh.getNumContacts(); out.maxContacts = MAX_CONTACTS;
  out.orphanedBlobs = the_mesh.getOrphanedBlobs();
  DataStore *store = the_mesh.getStore();
  if (store && store->lastContactsSaveValid()) {
    out.contactsSaveValid = true; out.contactsSaveInPlace = store->lastContactsSaveInPlace();
    out.contactsSaved = store->lastContactsSaveRecs(); out.contactsSaveMs = store->lastContactsSaveMs();
  }
#endif
}
