// Map tile source: false = tile server + on-device cache, true = read tiles off the microSD.
// The toggle + its callback (mapOptTilesSdCb) live in the map options popup, further down.
static bool s_tiles_from_sd = false;
// Map night mode: invert tile colours at render time only (the cached JPEG/PNG is
// never altered). Loaded from prefs at boot; toggled in the map options popup.
static bool s_map_night = false;

// Map tile style: 0 = OpenStreetMap (default), 1 = OpenTopoMap (topographic relief).
// Loaded from prefs at boot; toggled in the map options popup. Topo is namespaced
// in the on-disk cache (/tiles/topo) and fetched via the proxy's /opentopo route,
// so the OSM and topo caches never collide and toggling is instant for tiles that
// are already cached. SD map packs are OSM-only, so topo always uses the online
// cache + fetch (see loadTileJpeg / queueTileForFetch).
static uint8_t s_map_style = 0;
static inline const char* mapTileRoot()    { return s_map_style == 1 ? "/tiles/topo" : "/tiles"; }   // on-disk cache root

#if CAP_SD || defined(TLORA_PAGER)
// Store all data (identity/prefs/contacts/channels) on SD under /meshcomod vs
// internal SPIFFS. Read at boot before data loads, so it only takes effect on
// the next reboot.


#if defined(HAS_TDECK_GT911) || defined(HAS_TDECK_PRO) || defined(HELTEC_LORA_V4_R8) || defined(TLORA_PAGER) || defined(HAS_THINKNODE_M9)
// "Copy internal data to SD": recovery for the beta_36 upgrades where the live
// profile was orphaned on internal flash while the honored SD toggle adopted an
// empty card. Pager resumes only onto a card with no identity or the identical
// profile; legacy targets retain their explicit overwrite behavior. On success
// this forces the SD pref on and reboots.
extern bool meshcomodMigrateSpiffsToSd(bool force);   // main.cpp
extern bool meshcomodPrepareSdMigration();            // clears the prior commit marker / claims empty Pager tree
#if defined(TLORA_PAGER)
extern bool meshcomodSdProfileMatchesInternal();      // compares bytes without logging identity data
#endif
extern bool meshcomodArmSdMigLatch();                  // durable in-progress guard
extern void meshcomodClearSdMigLatch();               // main.cpp (GH #142/#148 boot safe-mode)
extern bool g_sd_migration_blocked;
extern bool g_full_data_on_sd;                         // boot chose SD for identity/prefs
static bool sdRuntimeLifecycleBusy();

static ui::services::SdRestoreJob::Host sdRestoreHost() {
  ui::services::SdRestoreJob::Host host{};
  host.lifecycleBusy = [](void*) { return sdRuntimeLifecycleBusy(); };
  host.mountSd = [](void*) { return fmSdTryMount(); };
  host.heavyWdtBegin = [](void*) { wdtHeavyBegin(); };
  host.heavyWdtEnd = [](void*) { wdtHeavyEnd(); };
  host.persistHistory = [](void*) { if (g_lv.task) g_lv.task->persistHistoryNow(); };
  host.flushDiscovered = [](void*) { discoveredFlushNow(); };
  host.flushContacts = [](void*) { the_mesh.flushContactsIfDirty(); };
  host.persistSyncHistory = [](void*) { the_mesh.persistSyncHistoryNow(); };
  host.flushPrefs = [](void*) { return touchPrefsFlush(); };
#if defined(TLORA_PAGER)
  host.profileMatches = [](void*) { return meshcomodSdProfileMatchesInternal(); };
#endif
  host.prepareMigration = [](void*) { return meshcomodPrepareSdMigration(); };
  host.armLatch = [](void*) { return meshcomodArmSdMigLatch(); };
  host.guardedMigration = [](void*, ui::services::SdRestoreJob::Status (*run)(void*),
                             void* runContext) {
    const UBaseType_t low_water = uxTaskGetStackHighWaterMark(nullptr);
    Serial.printf("[BOOT] deferred SD migration, loop stack low-water: %u bytes\n",
                  (unsigned)(low_water * sizeof(StackType_t)));
    LoopWdtGuard loop_wdt_guard;
    return run(runContext);
  };
  host.migrate = [](void*, bool forceCopy) { return meshcomodMigrateSpiffsToSd(forceCopy); };
  host.markBlocked = [](void*) { g_sd_migration_blocked = true; };
  host.clearLatch = [](void*) { meshcomodClearSdMigLatch(); };
  host.setUseSd = [](void*) { touchPrefsSetUseSdStorage(true); };
  host.clockFloor = [](void*) { return rtc_clock.getFloor(); };
  host.setClockFloor = [](void*, uint32_t floor) { touchPrefsSetClockFloor(floor); };
  host.delayMs = [](void*, unsigned milliseconds) { delay(milliseconds); };
  host.reboot = [](void*) { board.reboot(); };
  return host;
}

static ui::services::SdRestoreJob& sdRestoreJob() {
#if defined(TLORA_PAGER)
  static ui::services::SdRestoreJob job(
      sdRestoreHost(), ui::services::SdRestoreJob::Policy(true, false));
#else
  static ui::services::SdRestoreJob job(
      sdRestoreHost(), ui::services::SdRestoreJob::Policy(false, true));
#endif
  return job;
}

// The filesystem walk runs only after lv_timer_handler() has returned. On
// Pager it must not share LVGL's event/render stack with migration path buffers.
static void sdRestoreRun() {
  if (!g_lv.task) return;
  using Status = ui::services::SdRestoreJob::Status;
  switch (sdRestoreJob().tick()) {
    case Status::Idle:
    case Status::Deferred:
    case Status::RebootRequested:
      return;
    case Status::NoCard:
      g_lv.task->showAlert(TR("No SD card"), 1600);
      return;
    case Status::InternalBusy:
      g_lv.task->showAlert(TR("Copy blocked: internal data is busy"), 2600);
      return;
    case Status::ProfileMismatch:
      g_lv.task->showAlert(TR("Copy blocked: SD card holds a different or unreadable profile"), 3600);
      return;
    case Status::PrepareFailed:
      g_lv.task->showAlert(TR("Copy blocked: SD profile could not be prepared safely"), 3200);
      return;
    case Status::LatchFailed:
      g_lv.task->showAlert(TR("Copy blocked: migration guard unavailable"), 2600);
      return;
    case Status::CopyFailed:
      g_lv.task->showAlert(TR("Copy incomplete: SD data may be mixed. Retry before reboot."), 4200);
      return;
    case Status::InvalidHost:
      g_lv.task->showAlert(TR("Copy blocked: internal data is busy"), 2600);
      return;
  }
}

static void sdRestoreApply() {
  if (!g_lv.task || sdRestoreJob().pending()) return;
#if defined(TLORA_PAGER)
  g_lv.task->showAlert(TR("Resuming missing files to SD...\nThis may take a few minutes; keep powered."), 180000);
#else
  g_lv.task->showAlert(TR("Copying internal data to SD...\nThis may take a few minutes; keep powered."), 180000);
#endif
  sdRestoreJob().request();
}

#endif
#endif



