static void buildDeviceSettings(int sec) {
  // One detail page per section: each block below is gated to its DSEC_* section
  // (skipped blocks don't advance y, so every page lays out from the top).
  lv_obj_t* body = createSettingsModal("", SettingsModalKind::Device);
  if (sec == DSEC_GENERAL) {
    generalSettingsScreen.build(body, s_settings_content_w);
    return;
  }
  if (sec == DSEC_LOCK) {
    lockSettingsScreen.build(body, s_settings_content_w);
    return;
  }
  if (sec == DSEC_DISPLAY) {
    displaySettingsScreen.build(body, s_settings_content_w);
    return;
  }
  if (sec == DSEC_KEYBOARD) {
    keyboardSettingsScreen.build(body, s_settings_content_w);
    return;
  }
  if (sec == DSEC_SOUND) {
    soundScreen.build(body, s_settings_content_w);
    return;
  }
  if (sec == DSEC_BATTERY) {
    batterySettingsScreen.build(body, s_settings_content_w);
    return;
  }
  if (sec == DSEC_CLOCK) {
    clockScreen.build(body, s_settings_content_w, CAP_BOOT_TIME_SYNC);
    return;
  }
  int y = 0;

  if (sec == DSEC_GPS) {
    gpsScreen.build(body, s_settings_content_w, CAP_GPS);
    return;
  }

  if (sec == DSEC_SENSORS) {   // --- Sensors / expansion (V4-with-kit only) ---
#if defined(HAS_EXPANSION_KIT)
    lv_obj_t* b_exp = lv_btn_create(body);
    lv_obj_set_size(b_exp, lv_pct(100), SC(34));
    lv_obj_set_pos(b_exp, 2, y);
    styleButton(b_exp);
    lv_obj_add_event_cb(b_exp, openExpansionCardCb, LV_EVENT_CLICKED, nullptr);
    lv_obj_t* le = lv_label_create(b_exp);
    useChainedFont(le);
    lv_label_set_text(le, TR("Expansion Kit"));
    lv_obj_center(le);
    y += SC(38);
#endif
    // The "Show Sensors tab" toggle is appended here too (moved from Display).
  }


}

