// ----- Bluetooth settings page -----
// Hardware policy remains here; the screen owns widgets, captured keyboard
// identity, pairing choices, and callbacks across modal/inline navigation.
#if CAP_BLE_KEYBOARD
static void bleKbdApplyMode(); // key routing and phone-link pause live below
#endif
static void settingsPageRefit();

using BluetoothPage = ui::screens::BluetoothSettingsScreen;
#if CAP_BLE_KEYBOARD
static BluetoothPage::Device blePageDevice(const BleKbd::Device& source) {
  BluetoothPage::Device device;
  memcpy(device.name, source.name, sizeof device.name);
  device.name[sizeof device.name - 1] = '\0';
  memcpy(device.addr, source.addr, sizeof device.addr);
  device.addrType = source.addr_type;
  device.rssi = source.rssi;
  device.keyboard = source.keyboard;
  return device;
}
static BleKbd::Device bleCoreDevice(const BluetoothPage::Device& source) {
  BleKbd::Device device = {};
  memcpy(device.name, source.name, sizeof device.name);
  device.name[sizeof device.name - 1] = '\0';
  memcpy(device.addr, source.addr, sizeof device.addr);
  device.addr_type = source.addrType;
  device.rssi = source.rssi;
  device.keyboard = source.keyboard;
  return device;
}
static BluetoothPage::State blePageState(BleKbd::State state) {
  switch (state) {
    case BleKbd::State::Off: return BluetoothPage::State::Off;
    case BleKbd::State::Idle: return BluetoothPage::State::Idle;
    case BleKbd::State::Waiting: return BluetoothPage::State::Waiting;
    case BleKbd::State::Scanning: return BluetoothPage::State::Scanning;
    case BleKbd::State::Connecting: return BluetoothPage::State::Connecting;
    case BleKbd::State::Pairing: return BluetoothPage::State::Pairing;
    case BleKbd::State::Connected: return BluetoothPage::State::Connected;
    case BleKbd::State::Failed: return BluetoothPage::State::Failed;
  }
  return BluetoothPage::State::Off;
}
static BluetoothPage::Error blePageError(BleKbd::Error error) {
  switch (error) {
    case BleKbd::Error::None: return BluetoothPage::Error::None;
    case BleKbd::Error::NotRunning: return BluetoothPage::Error::NotRunning;
    case BleKbd::Error::Connect: return BluetoothPage::Error::Connect;
    case BleKbd::Error::PairingCode: return BluetoothPage::Error::PairingCode;
    case BleKbd::Error::PairingNoCode: return BluetoothPage::Error::PairingNoCode;
    case BleKbd::Error::NotKeyboard: return BluetoothPage::Error::NotKeyboard;
    case BleKbd::Error::NeedsPairing: return BluetoothPage::Error::NeedsPairing;
  }
  return BluetoothPage::Error::None;
}
#endif

static BluetoothPage::Host bluetoothSettingsHost() {
  BluetoothPage::Host host;
  host.readSnapshot = [](void*, BluetoothPage::Snapshot& out) -> bool {
    out = BluetoothPage::Snapshot{};
    out.bleCapable = g_lv.task && g_lv.task->hasBleCapability();
#if defined(ESP32) && defined(MULTI_TRANSPORT_COMPANION)
    out.radioControllable = true;
    out.wifiOn = wifiConfigGetRadioEnabled();
    out.bleRequested = bleRequestedOrEnabled();
#else
    out.radioControllable = false;
#endif
    out.bleActive = out.bleCapable && g_lv.task->isBleEnabled();
    const NodePrefs* prefs = the_mesh.getNodePrefs();
    out.pin = prefs ? prefs->ble_pin : 0;
#if CAP_BLE_KEYBOARD
    out.keyboardSupported = true;
    out.keyboardMode = touchPrefsGetBleKbdMode();
    out.keyboardActive = BleKbd::active();
    out.state = blePageState(BleKbd::state());
    out.error = blePageError(BleKbd::lastError());
    out.generation = BleKbd::generation();
    out.pairingCode = BleKbd::pairingCode();
    out.layout = static_cast<uint8_t>(BleKbd::layout());
    out.backKey = BleKbd::backKey();
    out.capturingKey = BleKbd::capturingKey();
    BleKbd::Device paired = {};
    out.paired = BleKbd::paired(&paired);
    if (out.paired) out.pairedDevice = blePageDevice(paired);
    // The settings page polls every UI tick; do not copy the scan list there.
    if (bluetoothSettingsScreen().pairingOpen()) {
      const int count = BleKbd::deviceCount();
      for (int i = 0; i < count && out.foundCount < BluetoothPage::FoundCapacity; ++i) {
        BleKbd::Device found = {};
        if (BleKbd::deviceAt(i, &found))
          out.found[out.foundCount++] = blePageDevice(found);
      }
    }
#endif
    // BleKbd getters take separate locks; this bounded UI snapshot is not an
    // atomic transport transaction. The owner verifies identity at actions.
    return true;
  };
  host.requestRadio = [](void*, bool enabled) -> bool {
#if defined(ESP32) && defined(MULTI_TRANSPORT_COMPANION)
    if (!g_lv.task || !g_lv.task->hasBleCapability()) return false;
    if (enabled) {
      if (!g_lv.task->enableBle()) return false;
    } else g_lv.task->disableBle();
#if CAP_BLE_KEYBOARD
    bleKbdApplyMode();
#endif
    refreshStatusLabels();
    return true;
#else
    (void)enabled;
    return false;
#endif
  };
  host.radioFailureText = [](void*) -> const char* {
#if defined(ESP32) && defined(MULTI_TRANSPORT_COMPANION)
    return bleEnableFailureText();
#else
    return TR("No Bluetooth on this device");
#endif
  };
  host.savePin = [](void*, uint32_t pin) -> bool { return the_mesh.setBLEPin(pin); };
  host.setKeyboardMode = [](void*, bool keyboard) -> bool {
#if CAP_BLE_KEYBOARD
    touchPrefsSetBleKbdMode(keyboard);
    bleKbdApplyMode();
    return true;
#else
    (void)keyboard;
    return false;
#endif
  };
  host.setLayout = [](void*, uint8_t layout) -> bool {
#if CAP_BLE_KEYBOARD
    if (layout >= static_cast<uint8_t>(BleKbd::Layout::Count)) return false;
    BleKbd::setLayout(static_cast<BleKbd::Layout>(layout));
    touchPrefsSetBleKbdLayout(layout);
    return true;
#else
    (void)layout;
    return false;
#endif
  };
  host.captureBackKey = [](void*, bool on) {
#if CAP_BLE_KEYBOARD
    BleKbd::captureKey(on);
#else
    (void)on;
#endif
  };
  host.formatBackKey = [](void*, uint8_t key, char* text, size_t capacity) {
#if CAP_BLE_KEYBOARD
    BleKbd::keyName(key, text, capacity);
#else
    if (capacity) text[0] = '\0';
    (void)key;
#endif
  };
  host.scanKeyboards = [](void*, bool on) {
#if CAP_BLE_KEYBOARD
    BleKbd::scan(on);
#else
    (void)on;
#endif
  };
  host.pairKeyboard = [](void*, const BluetoothPage::Device& device, bool withCode) -> bool {
#if CAP_BLE_KEYBOARD
    return BleKbd::pairDevice(bleCoreDevice(device), withCode);
#else
    (void)device; (void)withCode;
    return false;
#endif
  };
  host.forgetKeyboardIfMatches = [](void*, const BluetoothPage::Device& device) -> bool {
#if CAP_BLE_KEYBOARD
    return BleKbd::forgetIfMatches(bleCoreDevice(device));
#else
    (void)device;
    return false;
#endif
  };
  host.requestForgetConfirmation = [](void*, uint32_t token, const BluetoothPage::Device&) {
    // ConfirmDialog owns this value capture; an older popup can never read a
    // newer page's mutable selection or token.
    confirmDialog.showCaptured(
      TR("Forget this keyboard? You will need to pair it again."), TR("Forget"),
      [token]() { bluetoothSettingsScreen().confirmForget(token); }, false);
  };
  host.openPairingPage = [](void*) {
    lv_obj_t* body = createSettingsModal(TR("Pair a keyboard"), SettingsModalKind::BleKeyboard);
    if (body) bluetoothSettingsScreen().buildPairing(body, s_settings_content_w);
  };
  host.closePairingPage = [](void*) {
    if (g_set_modal.root && g_set_modal.kind == SettingsModalKind::BleKeyboard)
      closeSettingsModal();
  };
  host.syncKeyboard = [](void*) { kbMirrorSyncToReal(); };
  host.blurFromDelete = [](void*, lv_event_t* event) -> bool { return blurFromDelete(event); };
  host.attachPinTextArea = [](void*, lv_obj_t* field) { attachSettingsTaEvents(field); };
  host.styleLayoutDropdown = [](void*, lv_obj_t* dropdown) { styleDropdown(dropdown); };
  host.alert = [](void*, const char* text, unsigned durationMs) {
    if (g_lv.task) g_lv.task->showAlert(text, durationMs);
  };
  host.refitPage = [](void*) { settingsPageRefit(); };
  host.navDetachBeforeTreeMutation = [](void*) {
#if CAP_KEYPAD_NAV
    navDetachBeforeTreeMutation();
#endif
  };
  host.navDirty = [](void*) { navMarkDirty(); };
  return host;
}

