static uint16_t batteryFullMv() { return batterySettings.fullMv(); }
static bool batteryIsCharging(uint16_t mv) { return batterySettings.isCharging(mv); }
static uint16_t batteryMvSmoothed() { return batterySettings.publishedMv(millis()); }

static int batteryPercentFromMv(uint16_t mv);   // fwd decl (icon derives from %)
static const char* batteryGlyphForMv(uint16_t mv) {
  if (mv == 0)               return LV_SYMBOL_BATTERY_EMPTY;
  if (batteryIsCharging(mv)) return LV_SYMBOL_CHARGE;   // on USB power
  // Derive the icon from the (calibrated) percent so custom packs whose full
  // voltage differs from 4.2 V still fill the icon at their real 100%.
  const int pct = batteryPercentFromMv(mv);
  if (pct >= 90) return LV_SYMBOL_BATTERY_FULL;
  if (pct >= 65) return LV_SYMBOL_BATTERY_3;
  if (pct >= 40) return LV_SYMBOL_BATTERY_2;
  if (pct >= 15) return LV_SYMBOL_BATTERY_1;
  return LV_SYMBOL_BATTERY_EMPTY;
}

static int batteryPercentFromMv(uint16_t mv) { return batterySettings.percent(mv); }

// ----- SD wedge detection (flag side; the probe/remount lives in sdHealthTick) -----
// A runtime SD failure is a one-way door in arduino-esp32: one timed-out command
// latches STA_NOINIT (or a data-phase error leaves FR_DISK_ERR everywhere), while
// SD.cardType() keeps returning the type CACHED at mount — so every
// `cardType() != CARD_NONE` gate still passes, I/O fails silently, and nothing
// ever re-runs the mount ladder until a reboot power-cycles the card. Any SD
// user (loop task, core-0 worker, notify task) that sees SD I/O fail while the
// card is supposedly mounted stamps this; UITask::loop verifies with real I/O
// and remounts if the card wedged. Volatile store only — safe from any task.
static std::atomic<uint32_t> s_sd_fail_note_ms{0}; // workers report; UI consumes
static inline void sdNoteIoFailure() {
  const uint32_t m = (uint32_t)millis();
  s_sd_fail_note_ms = m ? m : 1;
}

