// ---- Settings backup: import file picker ------------------------------------
// Mirrors the lock-wallpaper picker UX: a full-screen list of *.json files on
// internal flash + (T-Deck) the SD card root. Picking one shows a short confirm
// then streams it through MyMesh::uiImportBackup and reboots so the imported
// radio/identity settings take effect. Lives OUTSIDE the HAS_TDECK_GT911 guard
// above because the Import button exists on both touch boards (the Heltec has
// no SD slot, so it lists internal flash only).
// Picker and settings list ownership live in BackupPickerScreen/BackupSettingsScreen.
// Internal filesystem that holds the .json backups: FFat on the Tanmatsu (the launcher already
// mounted the 'locfd' FAT data partition — SPIFFS isn't the writable store there, and FFat.begin()
// would fail on an already-mounted volume), plain SPIFFS on the T-Deck / V4. Mirrors the file
// manager's "Internal" root so a backup lands where the user can actually see + restore it.
static fs::FS* backupInternalFs() {
#if defined(HAS_TDISPLAY_P4)
  // The P4 hot store moved from FFat to LittleFS('storage') in beta_54 (#167);
  // FFat is never mounted here anymore, so opening it failed every backup (#231).
  return &LittleFS;
#elif defined(HAS_TANMATSU)
  return &FFat;      // FAT data partition (locfd), mounted at boot; no SPIFFS here
#else
  SPIFFS.begin(false);
  return &SPIFFS;
#endif
}
static fs::FS* backupSdFs() {
#if CAP_SD || defined(TLORA_PAGER)
  return fmSdTryMount() ? &SD : nullptr;
#elif defined(HAS_TANMATSU) || defined(HAS_TDISPLAY_P4) || defined(HAS_WIO_TRACKER_L2)
  return tanSdTryMount() ? &SD_MMC : nullptr;
#else
  return nullptr;
#endif
}

static ui::services::BackupOperations::Host backupOperationsHost() {
  ui::services::BackupOperations::Host host{};
  host.internal = [](void*) -> fs::FS* { return backupInternalFs(); };
  host.sd = [](void*) -> fs::FS* { return backupSdFs(); };
  host.importBackup = [](void*, File& f, int* channels, int* contacts) -> bool {
    return the_mesh.uiImportBackup(f, 0x1F, true, true, channels, contacts);
  };
  host.exportBackup = [](void*, Print& out, double lat, double lon) {
    the_mesh.uiExportBackup(out, lat, lon);
  };
  host.wdtBegin = [](void*) { wdtHeavyBegin(); };
  host.wdtEnd = [](void*) { wdtHeavyEnd(); };
  host.persistHistory = [](void*) { if (g_lv.task) g_lv.task->persistHistoryNow(); };
  host.setClockFloor = [](void*, uint32_t floor) { touchPrefsSetClockFloor(floor); };
  host.flushPrefs = [](void*) { touchPrefsFlush(); };
  host.waitHistoryWorker = [](void*) { uiHistWaitWorkerIdle(); };
  host.historyBusy = [](void*) { return history.busy(); };
  host.flushHistorySoon = [](void*) { if (g_lv.task) g_lv.task->flushHistorySoon(); };
#if CAP_SD || defined(TLORA_PAGER)
  host.resetUsesSd = true;
  host.resetChecksSdLifecycle = true;
  host.sdLifecycleBusy = [](void*) { return sdRuntimeLifecycleBusy(); };
  host.resetSdMountBackoff = [](void*) { s_sd_retry_after_ms = 0; };
  host.wipeSdData = [](void*) {
    if (!fmSdTryMount() || !sdProbeAlive()) return false;
    if (!SD.exists("/meshcomod"))
      return sdProbeAlive() && !SD.exists("/meshcomod");
    fmRmRecursive(&SD, "/meshcomod");
    // Preserve root-level map tiles and verify real I/O after the removal.
    return sdProbeAlive() && !SD.exists("/meshcomod");
  };
#endif
#if defined(TLORA_PAGER)
  host.resetRequiresVerifiedSd = true;
  host.sdMayHoldData = [](void*) {
    return board.sdCardState() != TLoraPagerBoard::SdCardState::Absent;
  };
#endif
  host.factoryReset = [](void*) { the_mesh.uiFactoryReset(); };
  host.restart = [](void*) { ESP.restart(); };
  return host;
}

