static lv_obj_t* backupProgressOverlay(const char* caption, lv_opa_t opacity) {
  lv_obj_t* overlay = lv_obj_create(lv_layer_top());
  lv_obj_remove_style_all(overlay);
  lv_obj_set_size(overlay, lv_disp_get_hor_res(nullptr), lv_disp_get_ver_res(nullptr));
  lv_obj_set_style_bg_color(overlay, lv_color_black(), LV_PART_MAIN);
  lv_obj_set_style_bg_opa(overlay, opacity, LV_PART_MAIN);
  lv_obj_clear_flag(overlay, LV_OBJ_FLAG_SCROLLABLE);
  lv_obj_t* label = lv_label_create(overlay);
  lv_label_set_text(label, caption);
  lv_obj_set_style_text_color(label, lv_color_hex(colors().COLOR_TEXT), LV_PART_MAIN);
  lv_obj_set_style_text_font(label, &font16(), LV_PART_MAIN);
  lv_obj_center(label);
  lv_refr_now(nullptr);
  return overlay;
}

static void doBackupImportChosen(const ui::services::BackupPath& selected) {
  if (!g_lv.task || selected.empty()) return;
  lv_obj_t* overlay = backupProgressOverlay(TR("Importing settings\xe2\x80\xa6"), LV_OPA_70);
  const ui::services::BackupOperations::ImportResult result = backupOperations().beginImport(selected);
  lv_obj_del(overlay);
  using Status = ui::services::BackupOperations::Status;
  if (result.status != Status::Success) {
    g_lv.task->showAlert(result.status == Status::StorageUnavailable
                             ? TR("Import: storage unavailable")
                             : TR("Import failed (bad/unreadable JSON)"),
                         result.status == Status::StorageUnavailable ? 2000 : 2400);
    return;
  }
  char message[80];
  snprintf(message, sizeof(message), "Imported %d contacts, %d channels.\nRebooting\xe2\x80\xa6",
           result.contacts, result.channels);
  g_lv.task->showAlert(message, 2600);
  lv_refr_now(nullptr);
  delay(2600);
  backupOperations().finishImport(rtc_clock.getFloor());
}

static void backupImportAdapter(void*, const ui::services::BackupPath& selected) {
  doBackupImportChosen(selected);
}

