static void backupMakeFilename(char* out, size_t cap) {
  uint32_t epoch = 0;
  if (mesh::RTCClock* rtc = the_mesh.getRTCClock()) epoch = rtc->getCurrentTime();
  backupOperations().makeFilename(epoch,
                                  wallClockIsCurrent() && epoch > ClockFloorRTC::MIN_VALID_EPOCH,
                                  millis() / 1000, out, cap);
}

static void doExportBackupFile(const char* filename) {
  if (!g_lv.task) return;
  lv_obj_t* overlay = backupProgressOverlay(TR("Exporting settings\xe2\x80\xa6"), LV_OPA_70);
  const ui::services::BackupOperations::ExportResult result =
      backupOperations().exportFile(filename, g_lv.task->getNodeLat(), g_lv.task->getNodeLon());
  lv_obj_del(overlay);
  if (result.status != ui::services::BackupOperations::Status::Success) {
    g_lv.task->showAlert(result.status == ui::services::BackupOperations::Status::Failed
                             ? TR("Save failed") : TR("Export failed (can't open file)"), 1800);
    return;
  }
  char message[120];
  snprintf(message, sizeof(message), "Saved %s:%s",
           result.backend == ui::services::BackupOperations::Backend::Sd ? "SD" : "internal",
           result.path);
  g_lv.task->showAlert(message, 2600);
}

static bool doDeleteBackupPath(const ui::services::BackupPath& selected) {
  return backupOperations().deleteFile(selected);
}

static void doFactoryReset() {
#if defined(ESP32)
  lv_obj_t* overlay = backupProgressOverlay(TR("Erasing everything\xe2\x80\xa6"), LV_OPA_COVER);
  delay(150); // Let the overlay reach the panel before blocking erase.
  const ui::services::BackupOperations::Status result = backupOperations().factoryReset();
  if (result == ui::services::BackupOperations::Status::Success) return;
  lv_obj_del(overlay);
  if (!g_lv.task) return;
  switch (result) {
    case ui::services::BackupOperations::Status::HistoryBusy:
      g_lv.task->showAlert(TR("Factory reset blocked: storage is busy"), 2600);
      break;
    case ui::services::BackupOperations::Status::SdBusy:
      g_lv.task->showAlert(TR("Factory reset blocked: SD activity is still running; close tools and retry."), 3600);
      break;
    case ui::services::BackupOperations::Status::SdIncomplete:
      g_lv.task->showAlert(TR("Factory reset incomplete: SD data may already be partially erased. Retry to finish, or remove the card before resetting internal data."), 6000);
      break;
    default:
      g_lv.task->showAlert(TR("Factory reset blocked: storage is busy"), 2600);
      break;
  }
#endif
}

