static ui::UiApplication& navigation() {
  uiApplication.configurePopups(k_popup_registry, sizeof(k_popup_registry) / sizeof(k_popup_registry[0]));
  return uiApplication;
}
static bool popupRegistryAny() { return navigation().anyPopup(); }
static bool popupRegistryAnyOver() { return navigation().anyPopup(true); }
static bool popupRegistryDismissTop() { return navigation().dismissTop() == ui::UiApplication::Dismiss::Closed; }
static int popupRegistryDismissTopAboveAppDrawer() { return static_cast<int>(navigation().dismissTop(true)); }
static bool popupRegistryBlocksSwipe() { return navigation().blocksSwipe(); }

#if CAP_KEYPAD_NAV
struct BackRouteContext { ui::back::Policy policy; };
static ui::back::BackNavigation s_back_navigation;

static ui::back::Result routeBack(ui::back::Policy policy, bool pressed) {
  BackRouteContext context{policy};
  ui::back::Host host{};
  host.context = &context;
  host.wizardOpen = [](void*) { return setupWizardScreen().visible(); };
  host.wizardBack = [](void*) { setupWizardScreen().back(); };
#if defined(HAS_M9_KEYBOARD)
  host.panMode = [](void*) { return ui::screens::map::panMode(); };
  host.mapActive = [](void*) { return getActiveTab() == MAP_TAB_INDEX; };
  host.clearPan = [](void*, bool announce) -> bool {
    // setPanMode only assigns the flag. The stale cleanup can continue the
    // same Back press because it invokes no UI callback or navigation change.
    ui::screens::map::setPanMode(false);
    if (announce && g_lv.task) g_lv.task->showAlert(TR("Map pan off"), 900);
    return !announce;
  };
  host.historyBack = [](void*) { return m9NavPop(); };
#endif
  host.dropdownOpen = [](void*) { return navOpenDropdown() != nullptr; };
  host.dismissDropdown = [](void*) { navPushTap(LV_KEY_ESC); };
  host.powerMenuOpen = [](void*) { return s_power_menu != nullptr; };
  host.closePowerMenu = [](void*) { closePowerMenu(); };
  host.controlCenterOpen = [](void*) { return s_cc_root != nullptr; };
  host.closeControlCenter = [](void*) { closeControlCenter(); };
  host.confirmOpen = [](void*) { return confirmDialog.isOpen(); };
  host.pageCloser = [](void*) -> ui::UiApplication::Close { return uiApplication.pageClose(); };
  host.popupOpen = [](void*) { return popupRegistryAny(); };
  host.popupAboveBase = [](void*) { return popupRegistryAnyOver(); };
  host.dismissPopup = [](void*) { return navigation().dismissTop(); };
  host.selectionMode = [](void*) { return s_ct_select_mode; };
  host.chatOwner = [](void*) -> void* { return navOpenChatPanel(); };
  host.closeChat = [](void*, void* owner) { closeChatPanel(static_cast<LvChatPanel*>(owner)); };
  host.onHome = [](void*) { return getActiveTab() == HOME_TAB_INDEX; };
  host.goHome = [](void* ctx) {
#if defined(HAS_M9_KEYBOARD)
    if (static_cast<BackRouteContext*>(ctx)->policy == ui::back::Policy::M9) {
      ui::screens::map::setPanMode(false);
      s_m9_nav_replaying = true;
      navGoToMainTab(HOME_TAB_INDEX);
      s_m9_nav_replaying = false;
      return;
    }
#else
    (void)ctx;
#endif
    navGoToMainTab(HOME_TAB_INDEX);
  };
  host.editing = [](void*) { return s_nav_ta_editing; };
  host.stopEditing = [](void*) { s_nav_ta_editing = false; };
  host.escape = [](void* ctx, bool down) {
    if (static_cast<BackRouteContext*>(ctx)->policy == ui::back::Policy::TanmatsuNav)
      navFifoPush(LV_KEY_ESC, down);
    else
      navPushTap(LV_KEY_ESC);
  };
  host.settingsFromControlCenter = [](void*) { return s_settings_sheet && s_settings_from_cc; };
  host.settingsSheetOpen = [](void*) { return s_settings_sheet != nullptr; };
  host.openControlCenter = [](void*) { openControlCenter(); };
  return s_back_navigation.route(policy, host, pressed);
}
#endif

// Last Wi-Fi STA disconnect reason, surfaced by wifiStaStatusBrief as
// "auth failed (rNN)". Defined HERE rather than in src/main.cpp because every
// target compiles this file, while the two ESP32-P4 targets are IDF builds with
// their own main.cpp -- the S3-only definition left both of them failing to link.
// The S3 Wi-Fi event handler in src/main.cpp writes it through an extern.
#if defined(ESP32)
volatile uint8_t g_wifi_last_disc_reason = 0;
#endif



