bool UITask::threadHasMessageHistory(int thread_idx) const { return _messages.threadHasMessageHistory(thread_idx); }

bool UITask::deleteMessageBySlot(int slot) {
  const bool changed = _messages.deleteMessageBySlot(slot, segMarkSeqDirty);
  if (changed) markMsgsDirty();
  return changed;
}

int UITask::clearThreadHistory(int thread_idx) {
  const int cleared = _messages.clearThreadHistory(thread_idx, segMarkSeqDirty);
  markThreadsDirty();
  if (cleared) markMsgsDirty();
  return cleared;
}



int UITask::getUnreadTotal() const { return _messages.getUnreadTotal(); }

bool UITask::allocMessageStore() {
  int capacity = MAX_UI_MESSAGES;
#if defined(ESP32)
  capacity = uiDataFsIsSdCard() ? MAX_UI_MESSAGES_SD : MAX_UI_MESSAGES;
  uiDataEnsureDirs();
#endif
  return _messages.allocate(capacity, ui::platform::allocate, ui::platform::release);
}
